const D = { scale: 1, n: 26, energy: .55, density: .5, speed: 1, hue: 285, spread: .55, wander: .5, x: .5, y: .45, style: 'stained-glass', act: 'meadow', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const PI = Math.PI, TAU2 = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const N = Math.max(8, Math.min(60, Math.round(P.n)));
const sty = P.style;
const add = (sty === 'thermal' || sty === 'iridescent' || sty === 'xray');

// ---- swarm state ----
if (!S.bf || S.bn !== N || S.bseed !== P.seed) {
  S.bf = [];
  for (let i = 0; i < N; i++) {
    S.bf.push({ x: width * 0.5, y: height * 0.5, px: width * 0.5, py: height * 0.5,
      ph: fr(i) * TAU2, sp: 0.45 + fr(i + 1) * 0.9, rad: 0.05 + fr(i + 2) * 0.16,
      hu: (fr(i + 3) - 0.5) * 90, sz: 0.75 + fr(i + 4) * 0.6, fl: fr(i + 5) * TAU2 });
  }
  S.bn = N; S.bseed = P.seed;
}

const inten = 0.35 + 0.65 * K.intensity;
// rest during low-intensity sections: 0 = flying, 1 = settled/landing
const rest = Math.max(0, Math.min(1, (0.42 - K.intensity) / 0.42));
const sec = ((Math.floor(K.section) % 8) + 8) % 8;

// act programs modulate spread / agitation / vertical bias
const ACT = {
  meadow: { spr: 1.0, agit: 1.0, ybias: 0.0, conv: 0.0 },
  storm:  { spr: 1.7, agit: 1.9, ybias: -0.08, conv: 0.0 },
  bloom:  { spr: 0.55 + 0.9 * (sec % 4) / 3, agit: 1.0 + 0.6 * (sec % 2), ybias: 0.0, conv: (sec % 4 === 3) ? 0.75 : 0.15 } };
const ac = ACT[P.act] || ACT.meadow;

const spr = P.spread * ac.spr;
const wob = P.wander * ac.agit;
const flySpd = (0.35 + 1.15 * P.energy) * P.speed * inten;

// drifting attractor centre (real-time, never re-phases)
const cx = width * (P.x + 0.20 * spr * Math.sin(K.t * 0.061 + P.seed) + 0.06 * Math.sin(K.t * 0.017));
const cy = height * (P.y + ac.ybias + 0.14 * spr * Math.sin(K.t * 0.049 * 1.3) + rest * 0.22);
const settle = 1 - rest * 0.7;

// ---- atmospheric drifting motes (density) ----
const nm = Math.floor(34 * P.density);
if (nm > 0) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < nm; i++) {
    const mx = (fr(i * 3 + 40) * width + K.t * (6 + fr(i + 41) * 14)) % width;
    const my = height * (0.1 + 0.8 * fr(i * 3 + 42)) + Math.sin(K.t * 0.4 + i) * u * 0.02;
    const ma = 3 + 4 * (0.5 + 0.5 * Math.sin(K.t * 0.7 + i * 1.7));
    fill(hw(P.hue + 40), 26, 92, ma * (0.5 + 0.5 * P.density));
    ellipse(mx, my, u * 0.006, u * 0.006);
  }
  blendMode(BLEND);
  pop();
}

// wing geometry (right side, local space; butterfly faces up)
function wing(s, op, fore) {
  beginShape();
  if (fore) {
    vertex(0, -s * 0.2);
    vertex(s * 1.35 * op, -s * 1.18);
    vertex(s * 1.95 * op, -s * 0.32);
    vertex(s * 1.15 * op, s * 0.12);
  } else {
    vertex(s * 0.18, s * 0.06);
    vertex(s * 1.28 * op, s * 0.5);
    vertex(s * 1.02 * op, s * 1.28);
    vertex(s * 0.16, s * 0.72);
  }
  endShape(CLOSE);
}

function paintWing(s, op, fore, glass, jewel, dk) {
  if (sty === 'xray') {
    noFill(); stroke(190, 60, 100, 70); strokeWeight(1.1);
    wing(s, op, fore);
    stroke(190, 40, 100, 45); strokeWeight(0.7);
    for (let v = 0; v < 3; v++) line(0, 0, s * (0.9 + v * 0.35) * op, (fore ? -1 : 1) * s * (0.35 + v * 0.32));
    noStroke();
  } else if (sty === 'iridescent') {
    noStroke();
    for (let l = 0; l < 3; l++) {
      fill(hw(glass[0] + l * 26 + Math.sin(K.t * 0.9 + l) * 18), 60 - l * 12, 100, 26);
      push(); translate(s * 0.2 * op, (fore ? -0.2 : 0.4) * s); scale(op, 1); wing(s, 1, fore); pop();
    }
    fill(hw(glass[0] + 60), 30, 100, 30); ellipse(s * 0.9 * op, (fore ? -0.4 : 0.6) * s, s * 0.5, s * 0.5);
  } else if (sty === 'ink') {
    noStroke();
    fill(hw(glass[0]), 12, 22, 46); wing(s, op, fore);
    fill(hw(glass[0]), 10, 14, 40);
    push(); translate(s * 0.12 * op, (fore ? -0.1 : 0.15) * s); scale(0.86 * op / (op || 1), 0.9); wing(s, op, fore); pop();
    stroke(hw(glass[0]), 14, 10, 60); strokeWeight(s * 0.06); noFill();
    line(s * 0.1, (fore ? -0.2 : 0.1) * s, s * 1.4 * op, (fore ? -0.7 : 0.9) * s);
    noStroke();
  } else if (sty === 'thermal') {
    noStroke();
    fill(248, 70, 26, 60); wing(s, op * 1.05, fore);
    fill(20, 90, 92, 66); push(); scale(0.7, 0.78); wing(s, op, fore); pop();
    fill(52, 20, 100, 70); ellipse(s * 0.7 * op, (fore ? -0.4 : 0.55) * s, s * 0.42, s * 0.42);
  } else {
    // stained-glass
    noStroke();
    fill(glass[0], glass[1], glass[2], 80); wing(s, op, fore);
    fill(jewel[0], jewel[1], jewel[2], 82);
    ellipse(s * (fore ? 1.1 : 0.85) * op, (fore ? -0.45 : 0.6) * s, s * 0.5, s * 0.5);
    stroke(dk, 30, 10, 96); strokeWeight(s * 0.11); noFill();
    wing(s, op, fore);
    line(0, 0, s * 1.5 * op, (fore ? -1 : 1) * s * 0.55);
    noStroke();
  }
}

// ---- update + render butterflies ----
noStroke();
if (add) blendMode(ADD);
for (let i = 0; i < N; i++) {
  const b = S.bf[i];
  const orbit = u * b.rad * (0.6 + spr) * settle;
  const jx = Math.sin(K.t * 2.6 * b.sp * P.speed + b.ph * 2) * u * 0.022 * wob * settle;
  const jy = Math.cos(K.t * 2.9 * b.sp * P.speed + b.ph) * u * 0.022 * wob * settle;
  let tx = cx + Math.cos(K.t * 0.5 * b.sp * flySpd + b.ph) * orbit + jx;
  let ty = cy + Math.sin(K.t * 0.42 * b.sp * flySpd + b.ph * 1.31) * orbit * 0.72 + jy;
  tx += (cx - tx) * ac.conv * 0.6;
  ty += (cy - ty) * ac.conv * 0.6;
  b.px = b.x; b.py = b.y; b.x = tx; b.y = ty;
  let ang = Math.atan2(b.y - b.py, b.x - b.px);
  if (Math.abs(b.x - b.px) + Math.abs(b.y - b.py) < 0.4) ang = b.la || 0; else b.la = ang;

  const s = u * 0.03 * P.scale * b.sz;
  const flapRate = rest > 0.5 ? 1.4 : (2.0 + 2.0 * P.energy);
  const flap = 0.5 + 0.5 * Math.sin(K.beat * TAU2 * flapRate * P.speed + b.fl + K.t * (rest > 0.5 ? 1.6 : 0));
  const op = 0.28 + 0.72 * (flap * 0.7 + A.treble * 0.3);
  const glass = [hw(P.hue + b.hu), 78, 96];
  const jewel = [hw(P.hue + b.hu + 45), 90, 100];
  const dk = hw(P.hue + b.hu + 200);

  push();
  translate(b.x, b.y);
  rotate(ang + PI / 2);
  // right wings
  paintWing(s, op, true, glass, jewel, dk);
  paintWing(s, op, false, glass, jewel, dk);
  // left wings (mirror)
  push(); scale(-1, 1);
  paintWing(s, op, true, glass, jewel, dk);
  paintWing(s, op, false, glass, jewel, dk);
  pop();
  // body + antennae
  if (sty === 'xray') { stroke(190, 50, 100, 80); strokeWeight(s * 0.12); line(0, -s * 0.9, 0, s * 0.9); noStroke(); }
  else if (sty !== 'iridescent') {
    noStroke(); fill(add ? hw(P.hue) : 0, add ? 40 : 0, add ? 100 : 12, add ? 70 : 92);
    ellipse(0, 0, s * 0.28, s * 1.5);
  }
  if (sty !== 'iridescent' && sty !== 'thermal') {
    stroke(sty === 'xray' ? 190 : (add ? hw(P.hue) : 0), sty === 'xray' ? 40 : (add ? 30 : 0), add ? 100 : 14, 80);
    strokeWeight(s * 0.05);
    const aw = Math.sin(K.t * 3 + b.fl) * s * 0.15;
    line(0, -s * 0.7, aw - s * 0.28, -s * 1.3);
    line(0, -s * 0.7, aw + s * 0.28, -s * 1.3);
    noStroke();
  }
  pop();
}
if (add) blendMode(BLEND);
drawingContext.shadowBlur = 0;
